<?php ob_start(); ?><h1>File changes</h1><p class="muted">Recent snapshot changes grouped by scan/site. Use filters to focus on SEO doorway indicators and root changes.</p><form><input class="input" name="path" placeholder="Path contains / keyword" value="<?= e($_GET['path']??'') ?>"> <select class="input" name="kind"><option value="">All changes</option><?php foreach(['new'=>'New files','modified'=>'Modified/recently changed','deleted'=>'Deleted files','webroot'=>'Web root files','htaccess'=>'.htaccess','google'=>'google*.html','php'=>'.php','html'=>'.html','seo'=>'SEO keywords'] as $k=>$label): ?><option value="<?= e($k) ?>" <?= ($_GET['kind']??'')===$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select> <button class="btn">Filter</button></form><table><tr><th>Site</th><th>Change</th><th>Path</th><th>Size</th><th>MTime</th><th>First seen</th><th>Last changed</th></tr><?php foreach($changes as $c): $kind=($c['is_missing']??0)?'deleted':(($c['first_seen_at']??'')===($c['last_seen_at']??'')?'new':'modified'); ?><tr><td><?= e($c['site_name'] ?? '') ?></td><td><span class="badge <?= $kind==='deleted'?'critical':($kind==='new'?'high':'medium') ?>"><?= e($kind) ?></span></td><td class="uri-cell"><code><?= e($c['relative_path'] ?: $c['path']) ?></code></td><td><?= e($c['size']) ?></td><td><?= e($c['mtime']) ?></td><td><?= e($c['first_seen_at']) ?></td><td><?= e($c['last_changed_at'] ?? '') ?></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
